import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.x7b91k6X.js";const p=JSON.parse('{"title":"漫画 · 第 6 话 性能与安全：Instruments 与 Keychain","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.06-performance-security.md","filePath":"comics/EP.06-performance-security.md","lastUpdated":1792677465000}'),n={name:"comics/EP.06-performance-security.md"};function i(s,e,c,l,d,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="漫画-·-第-6-话-性能与安全-instruments-与-keychain" tabindex="-1">漫画 · 第 6 话 性能与安全：Instruments 与 Keychain <a class="header-anchor" href="#漫画-·-第-6-话-性能与安全-instruments-与-keychain" aria-label="Permalink to &quot;漫画 · 第 6 话 性能与安全：Instruments 与 Keychain&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../06-performance-security">06-performance-security.md</a> ｜ 原画：<a href="./EP.06-performance-security.svg">EP.06-performance-security.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：App 启动 3.2 秒、滑动卡顿，token 还明文存在 UserDefaults 里。</li><li><strong>Runtime 长老</strong>：教她用 Instruments 量出瓶颈、用 Keychain 守住机密。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>性能问题不能靠感觉优化——你以为是图片大，实际是 <code>+load</code> 里同步初始化了五个 SDK。安全问题不能靠侥幸——token 存 UserDefaults 等于把钥匙放在门垫下。正确的做法是：用 Instruments（Time Profiler / Allocations / Leaks）先测量再定位；机密一律走 Keychain；网络层开 ATS + 证书绑定防中间人。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>两个典型坑：</p><ul><li><strong>性能</strong>：启动慢、列表滑动掉帧，但不知道卡在哪一行。凭感觉优化往往改了一堆无关代码，真正的瓶颈（主线程 IO、同步初始化、图片解码）纹丝不动。</li><li><strong>安全</strong>：把登录 token、API 密钥写进 <code>UserDefaults</code>。UserDefaults 本质是 plist 文件，越狱设备或备份可直接读取，等于明文。</li></ul><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><ul><li><strong>Instruments</strong>：Xcode 自带的性能分析套件。<code>Time Profiler</code> 看 CPU 耗时栈，<code>Allocations</code> 看内存分配，<code>Leaks</code> 查内存泄漏，<code>Energy Log</code> 看耗电。<strong>先测再改</strong>是铁律。</li><li><strong>Keychain</strong>：系统级加密存储，数据被 Apple 的 Secure Enclave 保护，App 卸载后仍保留（同开发者账号下可共享）。用 <code>kSecClassGenericPassword</code> 存储普通机密，<code>kSecAttrAccessibleWhenUnlocked</code> 控制访问时机。</li><li><strong>ATS（App Transport Security）</strong>：iOS 9+ 默认强制 HTTPS，阻止明文 HTTP。<code>Certificate Pinning</code>（证书绑定）把服务器证书的公钥哈希内置到 App，防止中间人用伪造证书窃听。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>启动优化三砍：</p><ol><li><strong>砍启动任务</strong>：把非首屏必需的 SDK 初始化从 <code>didFinishLaunching</code> 移到首屏渲染后；</li><li><strong>砍内存峰值</strong>：图片按需解码（<code>ImageIO</code> 按屏幕尺寸解码）、列表行复用、大循环包 <code>autoreleasepool</code>；</li><li><strong>机密进 Keychain</strong>：封装一个 <code>KeychainHelper</code>，统一读写 token / 密钥，禁止再用 UserDefaults。</li></ol><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>先测量再优化，Instruments 定位瓶颈，禁止凭感觉改代码。</li><li>机密（token/密钥）只存 Keychain，UserDefaults 只存非敏感配置。</li><li>ATS 强制 HTTPS + Certificate Pinning，防止中间人窃听流量。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么 Keychain 比 UserDefaults 更安全？App 卸载后 Keychain 数据还在吗？</p><p><strong>答</strong>：Keychain 数据由系统加密存储（底层是 AES 加密的 SQLite，密钥在 Secure Enclave），App 只能通过 Security 框架 API 访问自己 Keychain Group 里的数据，无法直接读文件。UserDefaults 是明文 plist。Keychain 数据在 App 卸载后默认保留（同 Team ID 下重装可恢复），这是有意设计——用户重装 App 不需要重新登录。如需卸载即清除，可在 <code>applicationWillTerminate</code> 时主动删除。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>运行 <code>swift run EnterprisePatterns</code>，查看 <code>SecureStore.swift</code> 的 Keychain 封装和 <code>PinningURLSession.swift</code> 的证书绑定实现；用 Xcode Open Developer Tool → Instruments 跑一次 Time Profiler。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>性能和安全加固了，可上线前怎么保证不把 bug 带出去？第 7 话《测试：XCTest 与质量门禁》，建一套能自动拦截坏代码的测试体系。</p>',24)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
